export function normalizeWorkshopDueTimeInput(value: unknown) {
  const time = cleanText(value);
  if (!time) return '';
  if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(time)) {
    throw new OrderInputValidationError('Время готовности цеха должно быть в формате ЧЧ:ММ.');
  }
  return time;
}


